param(
	[string]$CatalogPath = "godot/data/currencyinfo.json",
	[string]$OnlyCountry = ""
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function New-LocalizedMap {
	param([string]$Value, [string[]]$Locales)
	$map = [ordered]@{}
	foreach ($locale in $Locales) { $map[$locale] = $Value }
	return $map
}

function New-LocalizedArrayMap {
	param([string[]]$Values, [string[]]$Locales)
	$map = [ordered]@{}
	foreach ($locale in $Locales) { $map[$locale] = @($Values) }
	return $map
}

function New-ReviewStep {
	param(
		[string]$StepId,
		[string]$Method,
		[string]$Side,
		[string]$Equipment,
		[string]$Title,
		[string]$Instruction,
		[string]$Expected,
		[string[]]$Locales
	)
	return [ordered]@{
		step_id = $StepId
		method = $Method
		side = $Side
		equipment = $Equipment
		title_texts = New-LocalizedMap $Title $Locales
		instruction_texts = New-LocalizedMap $Instruction $Locales
		expected_texts = New-LocalizedMap $Expected $Locales
	}
}

function New-Note {
	param($Definition, [string[]]$Locales)
	$features = @($Definition.features)
	$summary = [string]$Definition.summary
	$watermark = [string]$Definition.watermark
	$imagePath = [string]$Definition.image_path
	$lightTitle = if ($Definition.ContainsKey("light_title")) { [string]$Definition.light_title } else { "Check the watermark" }
	$lightInstruction = if ($Definition.ContainsKey("light_instruction")) { [string]$Definition.light_instruction } else { "Hold the note against light and inspect the portrait watermark and denomination." }
	$lightExpected = if ($Definition.ContainsKey("light_expected")) { [string]$Definition.light_expected } else { "The portrait watermark and denomination are visible." }
	return [ordered]@{
		country = [string]$Definition.country
		currency = [string]$Definition.currency
		denomination = [string]$Definition.denomination
		image_path = $imagePath
		note_id = "{0}_{1}" -f [string]$Definition.currency, [string]$Definition.denomination
		series = [string]$Definition.series
		recognition = [ordered]@{
			front_reference = $imagePath
			denomination_tokens = @([string]$Definition.denomination)
			text_tokens = @($Definition.text_tokens)
		}
			review = [ordered]@{
				status = "ready"
				steps = @(
					(New-ReviewStep "watermark" "backlight" "front" "white_backlight" $lightTitle $lightInstruction $lightExpected $Locales),
				(New-ReviewStep "touch" "touch" "front" "none" "Feel the raised printing" "Run a fingertip over the raised printing and tactile marks." "Raised printing and tactile marks can be felt." $Locales)
			)
		}
		summary_text = $summary
		watermark_text = $watermark
		security_features = $features
		source = [string]$Definition.source
		source_url = [string]$Definition.source_url
		summary_texts = New-LocalizedMap $summary $Locales
		watermark_texts = New-LocalizedMap $watermark $Locales
		security_features_texts = New-LocalizedArrayMap $features $Locales
	}
}

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..")
$catalogFile = Join-Path $repoRoot $CatalogPath
$appStateFile = Join-Path $repoRoot "godot/scripts/core/app_state.gd"
$appStateSource = Get-Content -Raw -Encoding UTF8 -LiteralPath $appStateFile
$supportedLocales = [regex]::Match($appStateSource, 'const SUPPORTED_LOCALES := \[(?<values>[^\]]+)\]').Groups['values'].Value -split ',' | ForEach-Object { $_.Trim().Trim('"') }
$catalog = Get-Content -Raw -Encoding UTF8 -LiteralPath $catalogFile | ConvertFrom-Json

