	@{ country = "Islandia"; currency = "isk"; denomination = "5000"; series = "Current Icelandic króna series (2003 issue)"; image_path = "res://assets/bills_official/isk_5000_front.svg"; source = "Central Bank of Iceland official valid-banknotes page and official banknote image asset"; source_url = "https://sedlabanki.is/greidslumidlun/sedlar-og-mynt/sedlar-i-gildi/fimm-thusund-krona-sedill/"; text_tokens = @("SEÐLABANKI ÍSLANDS", "5000", "FIVE THOUSAND KRÓNUR", "RAGNHEIÐUR JÓNSDÓTTIR", "ICELAND", "2003"); summary = "The 5,000-krona note is the second-highest current Icelandic banknote denomination and the current design was introduced in 2003. It features Ragnheiður Jónsdóttir, Bishop Gísli Þorláksson and his former wives on the front, and Ragnheiður with two embroiderers on the reverse."; watermark = "Hold the 5,000-krona note against light to inspect the Jón Sigurðsson portrait watermark, the bright 5000 watermark, and the continuous metallic security thread marked 5000KR."; features = @("Metal foil with Ragnheiður Jónsdóttir and 1646–1715 details.", "Jón Sigurðsson portrait watermark and bright 5000 watermark.", "Three raised vertical blind-recognition bars.", "Metallic security thread with 5000KR text, microprinting, raised printing, and UV fluorescent 5000 panel.") }
	@{ country = "Islandia"; currency = "isk"; denomination = "2000"; series = "Current Icelandic króna series"; image_path = "res://assets/bills_official/isk_2000_front.svg"; source = "Central Bank of Iceland official valid-banknotes page, official banknote design article, and official banknote image asset"; source_url = "https://cb.is/payments/banknotes-and-coin/valid-banknotes-in-circulation/"; text_tokens = @("SEÐLABANKI ÍSLANDS", "2000", "TWO THOUSAND KRÓNUR", "JÓN STEFÁNSSON", "ICELAND"); summary = "The 2,000-krona note is the third-highest current Icelandic banknote denomination. The Central Bank of Iceland lists it as valid legal tender and identifies painter Jóhannes S. Kjarval on the front; the series uses Jón Sigurðsson watermarking, tactile marks, microprinting, and raised printing."; watermark = "Hold the 2,000-krona note against light to inspect the Jón Sigurðsson portrait watermark, the bright denomination watermark, and the security-thread details."; features = @("Jón Sigurðsson portrait watermark and denomination watermark.", "Braille/blind-recognition mark and raised printing for tactile identification.", "Microprinting and fine-line security patterns.", "Special banknote paper, serial numbering, and UV-reactive security details.") }
