$definitions += @(
	@{ country = "Islas Salomón"; currency = "sbd"; denomination = "100"; series = "Current Solomon Islands dollar series (upgraded issue)"; image_path = "res://assets/bills_official/sbd_100_front.jpg"; source = "Central Bank of Solomon Islands official currency banknotes page and official 100-dollar note image"; source_url = "https://www.cbsi.com.sb/financial-stability/currency-management/solomon-islands-dollar"; text_tokens = @("SOLOMON ISLANDS", "100", "ONE HUNDRED DOLLARS", "CENTRAL BANK OF SOLOMON ISLANDS", "CBSI"); summary = "The 100-dollar note is the highest regular denomination in the Solomon Islands dollar family. CBSI describes its flag, coat of arms, fishing imagery, coconut growing and harvesting scenes, and De La Rue production, together with a wide windowed security thread and eagle/CBSI watermark."; watermark = "Hold the 100-dollar note against light to inspect the eagle and CBSI watermark and the complete wide security thread carrying CBSI and 100 elements."; features = @("Wide windowed security thread with shark and crocodile coat-of-arms imagery.", "Eagle and CBSI watermark visible from both sides.", "Raised print on SOLOMON ISLANDS and detailed guilloche patterns.", "Transparent thread window, security text, and serial-number features.") }
	@{ country = "Islas Salomón"; currency = "sbd"; denomination = "50"; series = "CBSI Golden Jubilee commemorative polymer note (2026)"; image_path = "res://assets/bills_official/sbd_50_front.png"; source = "Central Bank of Solomon Islands official 2026 Golden Jubilee commemorative-note press release and official security infographic"; source_url = "https://www.cbsi.com.sb/article/press-release-no162026-cbsi-launches-commemorative-50-banknote-mark-golden-jubilee"; text_tokens = @("SOLOMON ISLANDS", "50", "FIFTY DOLLARS", "CENTRAL BANK OF SOLOMON ISLANDS", "CBSI", "1976", "2026"); summary = "The 2026 Golden Jubilee 50-dollar commemorative note is legal tender and available through commercial banks and ATMs nationwide. CBSI describes its polymer substrate, eagle-head and shell-money/Bokolo transparent window, Central Bank building reverse, and the transition from traditional shell money to digital payments."; watermark = "Tilt and hold the polymer 50-dollar note against light to inspect the CBSI 50 mirror-like effect, the eagle/shell-money window, and the green 50 visible through the window."; features = @("Polymer substrate with transparent window featuring an eagle head and CBSI 50/Bokolo elements.", "Iridescent swipe and mirror-like CBSI effect when tilted.", "Green 50 see-through feature and Central Bank building reverse.", "Ten embossed tactile dots beside the serial number for vision-impaired users.") }
	@{ country = "Islas Salomón"; currency = "sbd"; denomination = "40"; series = "Solomon Islands 40th Independence commemorative polymer note (2018)"; image_path = "res://assets/bills_official/sbd_40_front.jpg"; source = "Central Bank of Solomon Islands official currency banknotes page and official 40-dollar note image"; source_url = "https://www.cbsi.com.sb/financial-stability/currency-management/solomon-islands-dollar"; text_tokens = @("SOLOMON ISLANDS", "40", "FORTY DOLLARS", "INDEPENDENCE", "1978", "2018"); summary = "The 40-dollar commemorative note celebrates 40 years of Solomon Islands independence and is legal tender in circulation. CBSI identifies its polymer substrate, raised dots for blind and partially sighted users, transparent shell window containing 40, and shimmering gold print representing sound waves from the conch shell."; watermark = "Hold the polymer 40-dollar note against light to inspect the transparent shell window and the denomination 40 visible from both sides."; features = @("Polymer substrate with a transparent window and blue shell containing 40.", "Raised tactile dots for blind and partially sighted users.", "Shimmering gold print that represents conch-shell sound waves when tilted.", "Front-to-back see-through security element and durable polymer construction.") }
)

$definitions += @(
