	@{ country = "Jordania"; currency = "jod"; denomination = "10"; series = "Current Jordanian dinar fifth issue (2022)"; image_path = "res://assets/bills_official/jod_10_front.jpg"; source = "Central Bank of Jordan official fifth-issue page and fifth-issue statement; note image fallback from Numismag after repeated CBJ direct-image timeouts"; source_url = "https://www.cbj.gov.jo/EN/List/The_Fifth_Issue"; text_tokens = @("THE HASHEMITE KINGDOM OF JORDAN", "CENTRAL BANK OF JORDAN", "10", "TEN DINARS", "SHARIF HUSSEIN BIN ALI", "2022"); summary = "The 10-dinar note is Jordan's third-highest current denomination in the 2022 fifth issue. It combines Hashemite portraiture with Roman amphitheater imagery and includes the fifth issue's watermark, hidden denomination, 3D thread, holographic patch, raised printing, and tactile marks."; watermark = "Hold the 10-dinar note against light to inspect the portrait watermark, hidden 10, and the 3D security thread."; features = @("Portrait watermark and hidden denomination.", "Three-dimensional security thread and holographic/color-shifting patch.", "Raised printing and microprinted security patterns.", "Tactile signs for visually impaired users and UV/fine-line details.") }
