if (-not [string]::IsNullOrWhiteSpace($OnlyCountry)) {
	$definitions = @($definitions | Where-Object { [string]$_.country -eq $OnlyCountry })
}

# Cameroon/XAF remains blocked: BEAC assets were poster-derived and are not eligible for the catalog.
$definitions = @($definitions | Where-Object { [string]$_.country -ne "Cameroon" })

$existingIds = @($catalog.CurrencyInfo | ForEach-Object { [string]$_.note_id })
$newNotes = @()
foreach ($definition in $definitions) {
	$noteId = "{0}_{1}" -f [string]$definition.currency, [string]$definition.denomination
	if ($existingIds -contains $noteId) {
		if ([string]$definition.country -eq "Taiwan" -or [string]$definition.country -eq "Dominican Republic") {
			for ($index = 0; $index -lt @($catalog.CurrencyInfo).Count; $index++) {
				if ([string]$catalog.CurrencyInfo[$index].note_id -eq $noteId) {
					$catalog.CurrencyInfo[$index] = New-Note $definition $supportedLocales
					break
				}
			}
		}
		continue
	}
	$newNotes += New-Note $definition $supportedLocales
}

$catalog.CurrencyInfo = @($catalog.CurrencyInfo) + $newNotes
$catalog | ConvertTo-Json -Depth 100 | Set-Content -Encoding UTF8 -LiteralPath $catalogFile
Write-Output "Added $($newNotes.Count) release-ready banknotes."
